sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // implement resource here
	try {
        var targetSysId = request.pathParams.target_sys_id;
        var data = request.body.data;

        if (!targetSysId || !data) {
            response.setStatus(400);
            return {
                status: 'error',
                message: 'Missing target_sys_id path parameter or request body.'
            };
        }

        var gr = new GlideRecord('x_2307388_it_ass_0_asset_request');
        if (!gr.get(targetSysId)) {
            response.setStatus(404);
            return {
                status: 'error',
                message: 'Record not found with sys_id: ' + targetSysId
            };
        }

        var fields = [
            'opened_by',
            'requestor',
            'type_of_asset',
            'consumables',
            'company',
            'priority',
            'short_description',
            'description'
        ];

        for (var i = 0; i < fields.length; i++) {
            var field = fields[i];
            if (data[field] !== undefined && data[field] !== null) {
                gr.setValue(field, data[field]);
            }
        }

        var updatedSysId = gr.update();

        if (!updatedSysId) {
            response.setStatus(500);
            return {
                status: 'error',
                message: 'Failed to update record on target instance.'
            };
        }

        response.setStatus(200);
        return {
            status: 'updated',
            sys_id: gr.getUniqueValue(),
            number: gr.getValue('number')
        };

    } catch (ex) {
        response.setStatus(500);
        return {
            status: 'error',
            message: ex.getMessage()
        };
    }

})(request, response);
